import type { ComponentPropsWithoutRef, ElementType, ReactNode } from "react";

/** Standard Craft Matrix block fields used by Drive CMS wrappers. */
export interface CmsBlockData {
	id: string;
	uid: string;
	title: string;
	headline?: string | null;
	copy?: string | null;
	hero?: Array<{
		url: string;
		alt?: string | null;
		width?: number;
		height?: number;
	}>;
	button?: Array<{
		text?: string | null;
		linkText?: string | null;
		url?: string | null;
		linkUrl?: string | null;
		newWindow?: string | boolean | null;
	}>;
}

/**
 * CmsBlockData aligns with SharedBlockContent in @/lib/component-content:
 *   title, headline, copy → copy fields
 *   hero[0]               → image
 *   button[0]             → button
 */

export type EditableMode = "inline" | "panel" | "focus";

export interface CmsFieldMapping {
	cmsField: keyof CmsBlockData | "componentHandle";
	prop: string;
	label: string;
	editable?: EditableMode;
	/** e.g. "comma-list" to split headline into string[] */
	format?: "comma-list";
}

export interface CmsComponentMeta {
	enabled: boolean;
	usesBlockStyles?: boolean;
	fields: CmsFieldMapping[];
}

export interface EditableFieldProps {
	subfield: string;
	label: string;
	inline?: boolean;
	panelOnly?: boolean;
	className?: string;
	as?: ElementType;
	children: ReactNode;
}

export type EditableComponent = (
	props: EditableFieldProps,
) => ReactNode;

export interface CmsBlockContext {
	fieldHandle: string;
	blockId: string;
	blockUid: string;
	entryId?: string;
	Editable: EditableComponent;
}

export type CmsBlockProps<TProps extends Record<string, unknown> = Record<string, unknown>> =
	CmsBlockContext & {
		data: CmsBlockData;
	} & TProps;

export type CmsBlockComponent<TProps extends Record<string, unknown> = Record<string, unknown>> =
	(props: CmsBlockProps<TProps>) => ReactNode;

export function mapCommaList(value?: string | null): string[] {
	if (!value?.trim()) {
		return [];
	}

	return value
		.split(/[,;]+/)
		.map((part) => part.trim())
		.filter(Boolean);
}

export function getBlockButton(data: CmsBlockData) {
	return data.button?.[0];
}

export function getBlockImage(data: CmsBlockData) {
	return data.hero?.[0];
}

"use client";

import React from "react";

import FallingText from "@/registry/open-source/falling-text";

import {
	CmsBlockComponent,
	mapCommaList,
} from "./_types";

/**
 * Library-shaped CMS block — no CraftEditable or project imports.
 * Copy to component library: registry/cms/falling-text.block.tsx
 */
export const fallingTextCmsMeta = {
	enabled: true,
	usesBlockStyles: true,
	fields: [
		{
			cmsField: "title",
			prop: "text",
			label: "Text",
			editable: "inline",
		},
		{
			cmsField: "headline",
			prop: "highlightWords",
			label: "Highlight words",
			editable: "inline",
			format: "comma-list",
		},
	],
} as const;

export interface FallingTextBlockOptions {
	trigger?: "auto" | "scroll" | "click" | "hover";
	backgroundColor?: string;
	wireframes?: boolean;
	gravity?: number;
	fontSize?: string;
	mouseConstraintStiffness?: number;
}

export const FallingTextCmsBlock: CmsBlockComponent<FallingTextBlockOptions> = ({
	data,
	Editable,
	trigger = "hover",
	backgroundColor = "transparent",
	wireframes = false,
	gravity = 0.56,
	fontSize = "2rem",
	mouseConstraintStiffness = 0.9,
}) => {
	const highlightWords = mapCommaList(data.headline);

	return (
		<div className="mx-auto flex w-full max-w-4xl flex-col items-center px-6">
			{data.headline ? (
				<Editable
					subfield="headline"
					label="Highlight words"
					inline
					className="mb-4 w-full text-center"
				>
					<p className="text-sm text-neutral-500">
						Highlight: {data.headline}
					</p>
				</Editable>
			) : null}
			<Editable subfield="title" label="Falling text" className="w-full">
				<div className="h-[400px] w-full">
					<FallingText
						text={data.title}
						highlightWords={highlightWords}
						trigger={trigger}
						backgroundColor={backgroundColor}
						wireframes={wireframes}
						gravity={gravity}
						fontSize={fontSize}
						mouseConstraintStiffness={mouseConstraintStiffness}
					/>
				</div>
			</Editable>
		</div>
	);
};
